INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4403-4000-8000-000000000003', 'b1b2c3d4-4444-4000-8000-000000000004', 3, 'O Significado Esponsal', 'O corpo como dom e entrega', '{"text": "O conceito central da Teologia do Corpo \u00e9 o **significado esponsal do corpo**: a capacidade de expressar amor como doa\u00e7\u00e3o total de si.\n\n**\"O homem n\u00e3o pode viver sem amor. Ele permanece para si mesmo um ser incompreens\u00edvel se o amor n\u00e3o lhe for revelado.\"** \u2014 Redemptor Hominis, 10\n\nO corpo revela que fomos feitos para:\n- **Dar-nos** \u2014 o amor aut\u00eantico \u00e9 sempre dom de si\n- **Receber** \u2014 aceitar o dom do outro com rever\u00eancia\n- **Ser fecundos** \u2014 o amor gera vida, seja biol\u00f3gica ou espiritual\n\nO pecado original distorceu esta linguagem:\n- A **concupisc\u00eancia** reduz a pessoa a objeto\n- A **vergonha** indica a perda da inoc\u00eancia original\n- O **dom\u00ednio** substitui a comunh\u00e3o\n\nMas Cristo veio restaurar o plano original. Na cruz, Ele mostra o significado esponsal em sua plenitude: entrega total, livre, fiel e fecunda.", "scripture": "Ef 5,25 \u2014 Maridos, amai vossas esposas, como Cristo amou a Igreja e se entregou por ela."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;